import java.util.Scanner

const val INF: Long = 1L shl 28
const val MOD: Long = 1000000007

fun power(base: Long, expo: Long): Long {
    var num = 1L
    var i = expo
    while (i != 0L) {
        num *= base
        i--
    }
    return num
}

fun main() {
    val sc = Scanner(System.`in`)
    var t = 1L
    val sb = StringBuilder()
    while (t-- > 0) {
        val n = sc.nextLong()
        val m = sc.nextLong()
        val k = sc.nextLong()
        val nn = n.toInt()
        val a = LongArray(nn)
        for (idx in 0 until nn) a[idx] = sc.nextLong()
        a.sort()
        if (m <= k) {
            sb.append(0)
        } else {
            var sum = 0L
            var i = n
            var devices = m
            var soc = k
            while (sum < m && devices > soc && i >= 1) {
                i--
                sum += a[i.toInt()]
                devices -= a[i.toInt()]
                soc--
            }
            if (devices <= soc) {
                sb.append(n - i)
            } else {
                var i2 = n
                var used = 0L
                var ss = 0L
                var j = 0L
                while (i2 >= 1 && ss < m) {
                    i2--
                    if (used >= k * j && j >= 1) {
                        ss--
                    }
                    ss += a[i2.toInt()]
                    used++
                    if (used % k == 0L && used != 0L) {
                        j++
                    }
                }
                if (ss >= m) {
                    sb.append(used)
                } else {
                    sb.append(-1)
                }
            }
        }
    }
    print(sb)
}
